import{c as t,Q as l,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"Matmul模板参数","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul模板参数","slug":"matmul模板参数"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Matmul模板参数.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Matmul模板参数.md"}'),e={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Matmul模板参数.md"};function i(p,a,o,c,d,r){return l(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="matmul模板参数" tabindex="-1">Matmul模板参数 <a class="header-anchor" href="#matmul模板参数" aria-label="Permalink to &quot;Matmul模板参数&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>创建Matmul对象时需要传入：</p><ul><li><p>A、B、C、Bias的参数类型信息， 类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型、是否转置、数据排布和是否使能L1复用。</p></li><li><p>MatmulConfig信息（可选），用于配置Matmul模板信息以及相关的配置参数。不配置默认使能Norm模板。</p><p>针对Atlas 200I/500 A2 推理产品，当前只支持使能默认的Norm模板。</p></li><li><p>MatmulCallBackFunc回调函数信息（可选），用于配置左右矩阵从GM拷贝到A1/B1、计算结果从CO1拷贝到GM的自定义函数。当前支持如下产品型号：</p><p>Ascend 950PR/Ascend 950DT</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p><p>Kirin X90</p></li><li><p>MatmulPolicy信息（可选），用于配置Matmul可拓展模块策略。不配置使能默认模板策略。当前支持如下产品型号：</p><p>Ascend 950PR/Ascend 950DT</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p><p>Atlas 200I/500 A2 推理产品</p><p>Atlas 推理系列产品AI Core</p><p>Kirin X90</p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE = C_TYPE, const auto&amp; MM_CFG = CFG_NORM, class MM_CB = MatmulCallBackFunc&lt;nullptr, nullptr, nullptr&gt;, MATMUL_POLICY_DEFAULT_OF(MatmulPolicy)&gt;</span></span>
<span class="line"><span>using Matmul = AscendC::MatmulImpl&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG, MM_CB, MATMUL_POLICY&gt;;</span></span></code></pre></div><ul><li><p>A_TYPE、B_TYPE、C_TYPE类型信息通过<a href="./Matmul使用说明.html#table1188045714378">MatmulType</a>来定义。</p></li><li><p>auto类型的参数MM_CFG（可选）：</p><ul><li><p>支持MatmulConfig类型：</p><p>Matmul模板信息，具体内容见<a href="./MatmulConfig.html">MatmulConfig</a>。</p></li><li><p>支持MatmulApiStaticTiling类型：</p><p>MatmulApiStaticTiling参数说明见<a href="#table7939847143412">表1</a>。</p><p>MatmulApiStaticTiling结构体中包括一组常量化Tiling参数和MatmulConfig结构。这种类型参数的定义方式为，通过调用<a href="./MatmulConfig.html">MatmulConfig</a>章节中介绍的获取模板的接口，指定(singleM, singleN, singleK, baseM, baseN, baseK)参数，获取自定义模板；将该模板传入<a href="./GetMatmulApiTiling.html">GetMatmulApiTiling</a>接口，得到常量化的参数。这种常量化的方式将得到MatmulApiStaticTiling结构体中定义的一组常量化参数，可以优化Matmul计算中的Scalar计算。当前支持定义为MatmulApiStaticTiling常量化的Tiling参数的模板有：Norm、IBShare、MDL模板。MxMatmul场景支持定义为MatmulApiStaticTiling常量化的Tiling参数的模板有：Norm、MDL模板。</p></li></ul></li><li><p>MM_CB（可选），用于支持不同的搬入搬出需求，实现定制化的搬入搬出功能。具体内容见<a href="./MatmulCallBackFunc.html">MatmulCallBackFunc</a>。</p></li><li><p>MATMUL_POLICY_DEFAULT_OF(MatmulPolicy)（可选），用于配置Matmul可拓展模块的策略。当前支持不配置该参数（使能默认模板策略）或者配置1个MatmulPolicy参数。</p><p>MATMUL_POLICY_DEFAULT_OF定义如下，用于简化MATMUL_POLICY的类型声明。该模板参数的详细使用方式请参考<a href="./MatmulPolicy.html">MatmulPolicy</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MATMUL_POLICY_DEFAULT_OF(DEFAULT)      \\</span></span>
<span class="line"><span>template &lt;const auto&amp; = MM_CFG, typename ...&gt;  \\</span></span>
<span class="line"><span>        class MATMUL_POLICY = AscendC::Impl::Detail::DEFAULT</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> MatmulApiStaticTiling常量化Tiling参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>M, N, Ka, Kb, singleCoreM, singleCoreN, singleCoreK, baseM, baseN, baseK, depthA1, depthB1, stepM， stepN，stepKa，stepKb, isBias, transLength, iterateOrder, dbL0A, dbL0B, dbL0C, shareMode, shareL1Size, shareL0CSize, shareUbSize, batchM, batchN, singleBatchM, singleBatchN, mxTypePara</td><td>int32_t</td><td>与TCubeTiling结构体中各同名参数含义一致。本结构体中的参数是常量化后的常数值。</td></tr><tr><td>cfg</td><td>MatmulConfig</td><td>Matmul模板的参数配置。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 用户自定义回调函数</span></span>
<span class="line"><span>void DataCopyOut(const __gm__ void *gm, const LocalTensor&lt;int8_t&gt; &amp;co1Local, const void *dataCopyOutParams, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span>void CopyA1(const AscendC::LocalTensor&lt;int8_t&gt; &amp;aMatrix, const __gm__ void *gm, int row, int col, int useM, int useK, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span>void CopyB1(const AscendC::LocalTensor&lt;int8_t&gt; &amp;bMatrix, const __gm__ void *gm, int row, int col, int useK, int useN, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 定义创建对象时需要传入的A、B、C、Bias参数类型信息</span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用MDL模板，创建Matmul实例</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_MDL&gt; mm1; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::MatmulConfig mmConfig{false/*不使能Norm模板*/, true/*使能BasicBlock模板*/, false/*不使能MDL模板*/, 128/*Matmul计算时base块M轴长度*/, 128/*Matmul计算时base块N轴长度*/, 64/*Matmul计算时base块K轴长度*/};</span></span>
<span class="line"><span>mmConfig.enUnitFlag = false; // 不使能UnitFlag功能</span></span>
<span class="line"><span>// 使用自定义的mmConfig，创建Matmul实例</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, mmConfig&gt; mm2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用NORM模板、自定义的mmConfig和自定义的回调函数，创建Matmul实例</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_NORM, AscendC::MatmulCallBackFunc&lt;DataCopyOut, CopyA1, CopyB1&gt;&gt; mm3;</span></span></code></pre></div>`,18)])])}const M=t(e,[["render",i]]);export{m as __pageData,M as default};
